<?php if(!$row):?><div class="alert">Orden inexistente.</div><?php else:?><h1>Orden #<?=$row['id_orden']?></h1><div class="panel"><p><b>Equipo:</b> <?=htmlspecialchars($row['nombre_equipo'])?> · <b>Estado:</b> <?=$row['nombre_estado']?></p><p><b>Falla:</b> <?=htmlspecialchars($row['descripcion_falla'])?></p></div><?php if(in_array(Auth::user()['rol'],['administrador','tecnico'],true)):?><form class="panel form" method="post" action="<?=BASE_URL?>/ordenes/update"><input type="hidden" name="id" value="<?=$row['id_orden']?>"><label>Estado<select name="id_estado"><?php foreach($opt['estados'] as $x):?><option value="<?=$x['id_estado']?>" <?=$x['id_estado']==$row['id_estado']?'selected':''?>><?=$x['nombre_estado']?></option><?php endforeach;?></select></label><label>Diagnóstico<textarea name="diagnostico"><?=htmlspecialchars($row['diagnostico']??'')?></textarea></label><label>Solución<textarea name="solucion"><?=htmlspecialchars($row['solucion']??'')?></textarea></label><label>Observaciones<textarea name="observaciones"><?=htmlspecialchars($row['observaciones']??'')?></textarea></label><button class="btn">Actualizar trabajo</button></form><?php endif;?><h2>Actividades y repuestos</h2><div class="table-wrap"><table><tr><th>Actividad</th><th>Repuesto</th><th>Cantidad</th><th>Subtotal</th></tr><?php foreach($row['detalles'] as $d):?><tr><td><?=$d['descripcion_actividad']?></td><td><?=$d['nombre_repuesto']?></td><td><?=$d['cantidad']?></td><td><?=$d['subtotal']?></td></tr><?php endforeach;?></table></div><?php endif;?>

